  "file.c2_tower.props": {
    "Author": "Evening Breeze",
    "Scanned": "1999-12-20",
    "Notes": "Pencil writing on the back: It stands north of the sports ground / A little taller than everyone / I climb up / Not to see the distance / But so the distance / Can see me too"
  },
  "file.c2_tower.onProps.toast": "A poem is written on the back of the drawing.",
